(function ($) {

    // Get target scroll Y position
    function calcOffset(selector, opts) {
        var $el, scrollPos, result;

        $el = $(selector);

        if ($el[length] == 0)
            return NULL;

        scrollPos = $el[offset]()[TOP];

        // Anchor position
        switch (opts.anchor) {
            case "middle":
                result = scrollPos - ( $(window).height() - $el.outerHeight() ) / 2;
                break;

            default:
            case TOP:
                result = Math.max(scrollPos, 0);
        }

        // Apply offsets
        if (typeof opts[offset] == "function")
            result -= opts[offset]();
        else
            result -= opts[offset];

        return result;
    }

    var length = "length",
        NULL = null,
        TOP = "top",
        offset = "offset",
        clickEvent = "click.scrolly",
        $win = $(window);

    $.fn.scrolly = function (options) {

        var $this = $(this),
            customOffset,
            settings,
            hash;

        if (this[length] == 0)
            return $this;

        // If multiple matched elements, apply individually
        if (this[length] > 1) {
            for (var i = 0; i < this[length]; i++)
                $(this[i]).scrolly(options);
            return $this;
        }

        customOffset = NULL;
        hash = $this.attr("href");

        if (hash.charAt(0) != "#" || hash[length] < 2)
            return $this;

        settings = $.extend({
            anchor: TOP,
            easing: "swing",
            offset: 0,
            parent: $("body,html"),
            pollOnce: false,
            speed: 1000
        }, options);

        // Precompute?
        if (settings.pollOnce)
            customOffset = calcOffset(hash, settings);

        // Bind click
        $this
            .off(clickEvent)
            .on(clickEvent, function (evt) {

                // Calculate destination
                var dest = (customOffset !== NULL)
                    ? customOffset
                    : calcOffset(hash, settings);

                if (dest !== NULL) {
                    evt.preventDefault();
                    settings.parent.stop().animate(
                        { scrollTop: dest },
                        settings.speed,
                        settings.easing
                    );
                }
            });

    };

})(jQuery);
